import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BEUshCVJ.js";const b=JSON.parse('{"title":"设置项","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/settings.md","filePath":"zh/reference/settings.md","lastUpdated":1792715383000}'),r={name:"zh/reference/settings.md"};function a(i,t,h,s,n,l){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="设置项" tabindex="-1">设置项 <a class="header-anchor" href="#设置项" aria-label="Permalink to &quot;设置项&quot;">​</a></h1><p>本页列出所有设置项、在应用中的位置，以及它们在 <code>settings.json</code> 中的键名。通常在应用里修改即可；只有自动化部署或恢复时才需要手工编辑文件。</p><h2 id="where-settings-are-stored" tabindex="-1">设置保存位置 <a class="header-anchor" href="#where-settings-are-stored" aria-label="Permalink to &quot;设置保存位置 {#where-settings-are-stored}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>安装方式</th><th>设置文件夹</th></tr></thead><tbody><tr><td>Scoop</td><td><code>scoop\\persist\\meetcue\\config</code>（升级后保留）</td></tr><tr><td>便携 zip</td><td><code>MeetCue.exe</code> 同级的 <code>config</code></td></tr><tr><td>上述文件夹不可写时的回退位置</td><td><code>%APPDATA%\\MeetCue</code></td></tr></tbody></table><p>文件夹中有 <code>settings.json</code>、<code>latency-history.json</code>、<code>usage.jsonl</code>、<code>logs\\</code> 和 <code>practice\\</code>。<strong>设置 › 诊断 › 关于</strong> 会显示当前使用的文件夹。API 密钥不保存在这里，而是在 Windows 凭据管理器中。</p><p>如果 <code>settings.json</code> 无法读取，MeetCue 会把它重命名为 <code>settings.json.bad</code> 并以默认设置启动。</p><h2 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>界面语言</td><td><code>general.uiLanguage</code>：<code>system</code>、<code>en</code>、<code>zh-CN</code></td><td><code>system</code></td></tr><tr><td>提示语言</td><td><code>general.hintLanguage</code>：<code>followQuestion</code>、<code>en</code>、<code>zh-CN</code></td><td><code>followQuestion</code></td></tr><tr><td>强调色</td><td><code>general.accent</code></td><td><code>#F5B841</code></td></tr><tr><td>登录系统时启动 MeetCue</td><td><code>general.autostart</code></td><td><code>false</code></td></tr><tr><td>共享屏幕时隐藏面板</td><td><code>overlay.hideInScreenShare</code></td><td><code>true</code></td></tr><tr><td>鼠标穿透面板</td><td><code>overlay.clickThrough</code></td><td><code>false</code></td></tr></tbody></table><p>面板最后的形态（<code>overlay.mode</code>：<code>full</code>、<code>mini</code>、<code>hidden</code>）和位置（<code>overlay.x</code>、<code>overlay.y</code>）会自动记住。</p><h2 id="音频" tabindex="-1">音频 <a class="header-anchor" href="#音频" aria-label="Permalink to &quot;音频&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>麦克风（我）</td><td><code>audio.micDevice</code>；留空表示系统默认</td><td>空</td></tr><tr><td>与会者声音</td><td><code>audio.remoteSource</code>：<code>allSystemSound</code></td><td><code>allSystemSound</code></td></tr><tr><td>会议语言</td><td><code>audio.languages</code>，例如 <code>[&quot;zh&quot;, &quot;en&quot;]</code></td><td><code>[&quot;zh&quot;, &quot;en&quot;]</code></td></tr><tr><td>人声检测门限</td><td><code>audio.vadThresholdDb</code>，单位 dBFS</td><td><code>-45</code></td></tr><tr><td>静音多久算一句结束</td><td><code>audio.endpointSilenceMs</code></td><td><code>700</code></td></tr></tbody></table><h2 id="供应商与费用" tabindex="-1">供应商与费用 <a class="header-anchor" href="#供应商与费用" aria-label="Permalink to &quot;供应商与费用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th></tr></thead><tbody><tr><td>语音识别</td><td><code>providers.asr</code></td></tr><tr><td>问题检测模型</td><td><code>providers.detect</code></td></tr><tr><td>要点模型</td><td><code>providers.hints</code></td></tr><tr><td>AWS 区域（Bedrock）</td><td><code>providers.bedrockRegion</code></td></tr><tr><td>Base URL（OpenAI 兼容接口）</td><td><code>providers.openaiBaseUrl</code></td></tr><tr><td>HTTPS 代理</td><td><code>providers.proxy</code>；留空表示使用系统代理</td></tr><tr><td>手动填写的价格</td><td><code>providers.pricingOverrides</code></td></tr><tr><td>费用估算假设</td><td><code>providers.estimate</code></td></tr><tr><td>预算</td><td><code>providers.budget.sessionLimitUsd</code>、<code>monthlyLimitUsd</code>、<code>onLimit</code>（<code>notifyOnly</code>、<code>pauseHints</code>、<code>endSession</code>）</td></tr></tbody></table><p><code>asr</code>、<code>detect</code>、<code>hints</code> 各自包含 <code>provider</code>、<code>model</code> 和 <code>endpoint</code>。端点为 <code>{&quot;mode&quot;: &quot;auto&quot;}</code>（实测最快）或 <code>{&quot;mode&quot;: &quot;host&quot;, &quot;host&quot;: &quot;&lt;主机名&gt;&quot;}</code>。</p><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>我的角色</td><td><code>hints.role</code></td><td>空</td></tr><tr><td>会前资料</td><td><code>hints.materials</code>（名称、路径和抽取的文字）</td><td>无</td></tr><tr><td>只提示指向我的问题</td><td><code>hints.onlyDirectedToMe</code></td><td><code>false</code></td></tr><tr><td>插话自动排队</td><td><code>hints.queueInterruptions</code></td><td><code>true</code></td></tr><tr><td>跟踪已讲要点</td><td><code>hints.trackCoverage</code></td><td><code>true</code></td></tr><tr><td>提前触发</td><td><code>hints.earlyTrigger</code></td><td><code>true</code></td></tr></tbody></table><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>开始 / 暂停拾取</td><td><code>hotkeys.toggleCapture</code></td><td><code>Ctrl+Alt+Space</code></td></tr><tr><td>切换面板形态</td><td><code>hotkeys.cyclePanel</code></td><td><code>Ctrl+Alt+H</code></td></tr><tr><td>上一问</td><td><code>hotkeys.focusPrev</code></td><td><code>Ctrl+Alt+[</code></td></tr><tr><td>下一问</td><td><code>hotkeys.focusNext</code></td><td><code>Ctrl+Alt+]</code></td></tr><tr><td>标为已答</td><td><code>hotkeys.markAnswered</code></td><td><code>Ctrl+Alt+Enter</code></td></tr></tbody></table><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>播放方式</td><td><code>practice.playback</code>：<code>realPipeline</code>、<code>simulatedLatency</code></td><td><code>realPipeline</code></td></tr><tr><td>提示难度</td><td><code>practice.hintLevel</code>：<code>full</code>、<code>headsOnly</code>、<code>delayed</code>、<code>off</code></td><td><code>full</code></td></tr><tr><td>延迟显示的秒数</td><td><code>practice.hintDelayS</code></td><td><code>5</code></td></tr><tr><td>停顿多久算答完（秒）</td><td><code>practice.answerPauseS</code></td><td><code>3</code></td></tr><tr><td>未开口提醒（秒）</td><td><code>practice.nudgeAfterS</code></td><td><code>20</code></td></tr><tr><td>追问概率</td><td><code>practice.followUpProbability</code></td><td><code>0.3</code></td></tr><tr><td>朗读语速</td><td><code>practice.speechRate</code></td><td><code>1.0</code></td></tr><tr><td>识别我的回答</td><td><code>practice.recognizeMe</code></td><td><code>true</code></td></tr><tr><td>我开口时停止朗读</td><td><code>audio.stopTtsOnSpeech</code></td><td><code>true</code></td></tr><tr><td>口头禅词表</td><td><code>practice.fillersZh</code>、<code>practice.fillersEn</code></td><td>见<a href="/meetcue/zh/guide/practice#review-report">练习模式</a></td></tr></tbody></table><h2 id="诊断" tabindex="-1">诊断 <a class="header-anchor" href="#诊断" aria-label="Permalink to &quot;诊断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>键名</th><th>默认值</th></tr></thead><tbody><tr><td>调试日志</td><td><code>diagnostics.debugLogging</code></td><td><code>false</code></td></tr></tbody></table>',22)])])}const p=d(r,[["render",a]]);export{b as __pageData,p as default};
